(N'PERMISO|magis_api|SCHEMA|dbo|INSERT',N'E352AC0453AE4AB1E9FF1B3EAF6B6F0C3C3AD7F56144FDF60478EE768C34BA4F'),
(N'PERMISO|magis_api|SCHEMA|dbo|SELECT',N'E352AC0453AE4AB1E9FF1B3EAF6B6F0C3C3AD7F56144FDF60478EE768C34BA4F'),
(N'PERMISO|magis_api|SCHEMA|dbo|UPDATE',N'E352AC0453AE4AB1E9FF1B3EAF6B6F0C3C3AD7F56144FDF60478EE768C34BA4F'),
(N'PERMISO|magis_api|SCHEMA|api|EXECUTE',N'175DC5864FF59F71AD70C96401E0D61D6BCF5DCFEFE62CBFB3EDF9C1651548C4');
;WITH Metadatos AS (
 SELECT CONVERT(nvarchar(4000),CONCAT('TABLA|',s.name,'.',t.name)) COLLATE DATABASE_DEFAULT Clave,
 CONVERT(nvarchar(max),CONCAT(t.is_memory_optimized,'|',t.temporal_type)) COLLATE DATABASE_DEFAULT Valor
 FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE t.is_ms_shipped=0
 UNION ALL
 SELECT CONVERT(nvarchar(4000),CONCAT('COLUMNA|',s.name,'.',t.name,'.',c.name)) COLLATE DATABASE_DEFAULT,
 CONVERT(nvarchar(max),CONCAT(c.column_id,'|',ty.name,'|',c.max_length,'|',c.precision,'|',c.scale,'|',c.is_nullable,'|',c.is_identity,'|',c.collation_name,'|',cc.definition,'|',dc.definition,'|',CONVERT(nvarchar(100),ic.seed_value),'|',CONVERT(nvarchar(100),ic.increment_value))) COLLATE DATABASE_DEFAULT
 FROM sys.columns c JOIN sys.tables t ON t.object_id=c.object_id JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id
 LEFT JOIN sys.computed_columns cc ON cc.object_id=c.object_id AND cc.column_id=c.column_id
 LEFT JOIN sys.default_constraints dc ON dc.object_id=c.default_object_id
 LEFT JOIN sys.identity_columns ic ON ic.object_id=c.object_id AND ic.column_id=c.column_id WHERE t.is_ms_shipped=0
 UNION ALL
 SELECT CONVERT(nvarchar(4000),CONCAT('MODULO|',s.name,'.',o.name)) COLLATE DATABASE_DEFAULT,
 CONVERT(nvarchar(max),CONCAT(o.type,'|',m.uses_ansi_nulls,'|',m.uses_quoted_identifier,'|',m.definition)) COLLATE DATABASE_DEFAULT
 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE o.is_ms_shipped=0
 UNION ALL
 SELECT CONVERT(nvarchar(4000),CONCAT('CHECK|',OBJECT_SCHEMA_NAME(c.parent_object_id),'.',OBJECT_NAME(c.parent_object_id),'|',c.definition)) COLLATE DATABASE_DEFAULT,
 CONVERT(nvarchar(max),CONCAT(c.is_disabled,'|',c.is_not_trusted,'|',c.parent_column_id)) COLLATE DATABASE_DEFAULT
 FROM sys.check_constraints c WHERE c.is_ms_shipped=0
 UNION ALL
 SELECT CONVERT(nvarchar(4000),CONCAT('FK|',OBJECT_SCHEMA_NAME(f.parent_object_id),'.',OBJECT_NAME(f.parent_object_id),'|',OBJECT_SCHEMA_NAME(f.referenced_object_id),'.',OBJECT_NAME(f.referenced_object_id),'|',x.Mapa)) COLLATE DATABASE_DEFAULT,
 CONVERT(nvarchar(max),CONCAT(f.delete_referential_action,'|',f.update_referential_action,'|',f.is_disabled,'|',f.is_not_trusted)) COLLATE DATABASE_DEFAULT
 FROM sys.foreign_keys f CROSS APPLY(SELECT (
 SELECT pc.name Columna,rc.name Referencia FROM sys.foreign_key_columns k
 JOIN sys.columns pc ON pc.object_id=k.parent_object_id AND pc.column_id=k.parent_column_id
 JOIN sys.columns rc ON rc.object_id=k.referenced_object_id AND rc.column_id=k.referenced_column_id
 WHERE k.constraint_object_id=f.object_id ORDER BY k.constraint_column_id FOR JSON PATH) Mapa)x WHERE f.is_ms_shipped=0
 UNION ALL
 SELECT CONVERT(nvarchar(4000),CONCAT('INDICE|',OBJECT_SCHEMA_NAME(i.object_id),'.',OBJECT_NAME(i.object_id),'|',i.type,'|',i.is_unique,'|',x.Columnas,'|',i.filter_definition)) COLLATE DATABASE_DEFAULT,
 CONVERT(nvarchar(max),CONCAT(i.is_primary_key,'|',i.is_unique_constraint,'|',i.is_disabled)) COLLATE DATABASE_DEFAULT
 FROM sys.indexes i JOIN sys.tables t ON t.object_id=i.object_id CROSS APPLY(SELECT (
 SELECT c.name Columna,k.key_ordinal Orden,k.is_descending_key Descendente,k.is_included_column Incluida FROM sys.index_columns k JOIN sys.columns c ON c.object_id=k.object_id AND c.column_id=k.column_id
 WHERE k.object_id=i.object_id AND k.index_id=i.index_id ORDER BY k.index_column_id FOR JSON PATH) Columnas)x WHERE t.is_ms_shipped=0 AND i.index_id>0
 UNION ALL
 SELECT CONVERT(nvarchar(4000),CONCAT('SECUENCIA|',SCHEMA_NAME(q.schema_id),'.',q.name)) COLLATE DATABASE_DEFAULT,
 CONVERT(nvarchar(max),CONCAT(TYPE_NAME(q.user_type_id),'|',CONVERT(nvarchar(100),q.start_value),'|',CONVERT(nvarchar(100),q.increment),'|',CONVERT(nvarchar(100),q.minimum_value),'|',CONVERT(nvarchar(100),q.maximum_value),'|',q.is_cycling,'|',q.is_cached)) COLLATE DATABASE_DEFAULT
 FROM sys.sequences q WHERE q.is_ms_shipped=0
 UNION ALL
 SELECT CONVERT(nvarchar(4000),CONCAT('PERMISO|magis_api|',p.class_desc,'|',COALESCE(SCHEMA_NAME(p.major_id),''),'|',p.permission_name)) COLLATE DATABASE_DEFAULT,
 CONVERT(nvarchar(max),p.state_desc) COLLATE DATABASE_DEFAULT
 FROM sys.database_permissions p JOIN sys.database_principals r ON r.principal_id=p.grantee_principal_id WHERE r.name='magis_api'
)
INSERT @Actual(Clave,Firma) SELECT Clave,CONVERT(varchar(64),HASHBYTES('SHA2_256',Valor),2) Firma FROM Metadatos;



IF EXISTS(SELECT Clave,Firma FROM @Esperado EXCEPT SELECT Clave,Firma FROM @Actual)
OR EXISTS(SELECT Clave,Firma FROM @Actual EXCEPT SELECT Clave,Firma FROM @Esperado)
BEGIN
 SELECT N'Falta o difiere' Diferencia,Clave,Firma FROM(SELECT Clave,Firma FROM @Esperado EXCEPT SELECT Clave,Firma FROM @Actual)e
 UNION ALL SELECT N'Adicional o diferente',Clave,Firma FROM(SELECT Clave,Firma FROM @Actual EXCEPT SELECT Clave,Firma FROM @Esperado)a;
 THROW 52202,'La estructura o los modulos no coinciden con la version validada. Compartir las diferencias.',1;
END;
